package com.vandorlabs.client;
import com.google.gson.*;
import java.io.*;
import java.security.MessageDigest;
/** Standard Forge runtime classpath pixels, including full-height company artwork. */
public final class DoorPixelsLegacyChecks {
 public static void main(String[] args)throws Exception{
  JsonObject manifest=new JsonParser().parse(new FileReader(args[0])).getAsJsonObject(),previous=new JsonParser().parse(new FileReader(args[1])).getAsJsonObject(),result=new JsonObject();int checked=0;
  for(JsonElement value:manifest.getAsJsonArray("textures")){JsonObject entry=value.getAsJsonObject();String id=entry.get("original").getAsString(),relative=id.split(":",2)[1];InputStream stream=DoorPixelsLegacyChecks.class.getResourceAsStream("/assets/vandorlabs/textures/"+relative+".png");if(stream==null)stream=new SharedTextureResources().getInputStream(new net.minecraft.util.ResourceLocation("vandorlabs","textures/"+relative+".png"));java.awt.image.BufferedImage image;try(InputStream input=stream){image=javax.imageio.ImageIO.read(input);}MessageDigest hash=MessageDigest.getInstance("SHA-256");for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++){int color=image.getRGB(x,y);hash.update((byte)(color>>>16));hash.update((byte)(color>>>8));hash.update((byte)color);hash.update((byte)(color>>>24));}StringBuilder digest=new StringBuilder();for(byte b:hash.digest())digest.append(String.format("%02x",b&255));JsonObject pixels=new JsonObject();pixels.addProperty("height",image.getHeight());pixels.addProperty("rgbaSha256",digest.toString());pixels.addProperty("width",image.getWidth());if(previous.has(id)&&!previous.get(id).equals(pixels))throw new AssertionError("Existing frozen standard pixels changed "+id+" previous="+previous.get(id)+" actual="+pixels);result.add(id,pixels);checked++;}
  JsonObject policy=new JsonParser().parse(new FileReader(new File(new File(args[0]).getParentFile(),"door_material_policy.json"))).getAsJsonObject();int policies=0;
  for(int index=0;index<com.vandorlabs.tiles.ScreenHousingTextures.IDS.length;index++){String id=com.vandorlabs.tiles.ScreenHousingTextures.IDS[index];if(!policy.has(id))continue;int choice=com.vandorlabs.tiles.ScreenHousingTextures.choiceAt(index);JsonObject actual=policy.getAsJsonObject(id);if(actual.get("mirrored").getAsBoolean()!=com.vandorlabs.tiles.ScreenHousingTextures.mirroredDoorArtwork(choice)||actual.get("reversed").getAsBoolean()!=com.vandorlabs.tiles.ScreenHousingTextures.reversedDoorArtwork(choice)||actual.get("light").getAsBoolean()!=com.vandorlabs.tiles.ScreenHousingTextures.companyLight(choice))throw new AssertionError("Released artwork policy "+id);policies++;}if(policies!=policy.size())throw new AssertionError("Incomplete actual artwork policy coverage "+policies+"/"+policy.size());
  if(checked!=68)throw new AssertionError("Incomplete Door pixel inventory "+checked);try(Writer output=new OutputStreamWriter(new FileOutputStream(args[1]),"UTF-8")){java.util.Map<String,JsonElement> sorted=new java.util.TreeMap<>();for(java.util.Map.Entry<String,JsonElement> entry:result.entrySet())sorted.put(entry.getKey(),entry.getValue());new GsonBuilder().setPrettyPrinting().create().toJson(sorted,output);output.write("\n");}System.out.println("Door standard Forge pixel reference PASS sprites="+checked+" artworkPolicies="+policies+" retained previous50 exact; company18 full128x256");
 }
}
